const allItems = $input.all();

const processedItems = allItems.map(item => {
  const rawText = item.json.text_block || '';

  // 1. Extract Unique Profile ID and URL
  const urlMatch = rawText.match(/(https:\/\/news\.ycombinator\.com\/user\?id=([a-zA-Z0-9_-]+))/i);
  const uniqueProfileUrl = urlMatch ? urlMatch[1] : `hn-fallback-${Math.random().toString(36).substr(2, 9)}`;
  const userId = urlMatch ? urlMatch[2] : 'unknown';

  // 2. Extract Company Name
  const companyMatch = rawText.match(/^([a-zA-Z0-9_-]+)\s+\[/);
  const companyName = companyMatch ? companyMatch[1].trim() : userId;

  // 3. Extract Date Posted
  const dateMatch = rawText.match(/\](\d{4}-\d{2}-\d{2})/);
  const datePosted = dateMatch ? dateMatch[1] : '2026-06-01';

  // 4. Extract Job Description
  const dateIndex = rawText.indexOf(datePosted);
  let description = '';
  if (dateIndex !== -1) {
    description = rawText.substring(dateIndex + datePosted.length).trim();
  } else {
    description = rawText.replace(/^.*\]\d{4}-\d{2}-\d{2}/s, '').trim();
  }

  // 5. Heuristic Job Title Extraction (Fixed for Length Fallbacks and Spaces)
  const headerChunk = description.substring(0, 250).replace(/\n/g, ' ');
  let jobTitle = '';

  if (headerChunk.includes('|')) {
    const parts = headerChunk.split('|');
    jobTitle = parts[1] ? parts[1].trim() : parts[0].trim();

    let cleanCheck = jobTitle.replace(/remote|hybrid|full-time|fulltime|full\s+time|contract|onsite|on-site/gi, '').trim();

    if ((cleanCheck.length < 3 || jobTitle.includes('[') || jobTitle.includes('http')) && parts[2]) {
      jobTitle = parts[2].trim();
    }
  } else {
    jobTitle = description.split('\n')[0] || '';
  }

  jobTitle = jobTitle.replace(/remote|hybrid|full-time|fulltime|full\s+time|contract|onsite|on-site/gi, '').replace(/^[-\s|]+|[-\s|]+$/g, '').trim();
  jobTitle = jobTitle.replace(/\[http.*\]/gi, '').replace(/https?:\/\/\S+/gi, '').trim();

  if (jobTitle.length > 100 || jobTitle.length < 5) {
    jobTitle = jobTitle.substring(0, 70).trim() || description.substring(0, 50).replace(/\n/g, ' ').trim();
  }

  // 6. Extract Email Contacts
  const emailRegex = /([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/i;
  const emailMatch = description.match(emailRegex);
  const contactEmail = emailMatch ? emailMatch[1] : '';

  // 7. Extract Application URL with Domain and Truncation Exclusions
  const urlRegex = /(https?:\/\/[^\s\]\)\"\'>]+)/gi;
  const rawUrls = description.match(urlRegex) || [];

  const validUrls = rawUrls.map(url => url.replace(/[.,;)]$/, '')).filter(url => {
    const lowUrl = url.toLowerCase();
    return !lowUrl.includes('news.ycombinator.com') && 
           !lowUrl.includes('github.com') && 
           !lowUrl.includes('drive.google.com') && 
           !lowUrl.includes('twitter.com') &&
           !lowUrl.includes('..'); 
  });

  let applyUrl = '';

  for (const url of validUrls) {
    if (/apply|career|job|lever|greenhouse|ashby/i.test(url)) {
      applyUrl = url;
      break;
    }
  }

  if (!applyUrl && validUrls.length > 0) {
    applyUrl = validUrls[0];
  }

  if (!applyUrl && contactEmail) {
    applyUrl = `mailto:${contactEmail}`;
  }

  if (!applyUrl) {
    applyUrl = 'https://hnhiring.com/locations/remote';
  }

  return {
    json: {
      job_id_url: uniqueProfileUrl,
      company_name: companyName,
      posted_date: datePosted,
      job_title: jobTitle || 'Unknown Title',
      apply_url: applyUrl,
      email: contactEmail,
      description: description
    }
  };
});

return processedItems;

const platformName = "hackernews";

for (const item of $input.all()) {
  item.json.source = platformName;
}

return $input.all();

// Check the primary data entry points from the HTML node
const inputData = $input.first().json;
let rawTextArray = null;

if (Array.isArray(inputData)) {
  rawTextArray = inputData;
} else if (inputData && typeof inputData === 'object') {
  // Target the first property key if n8n wrapped the array inside an object field
  const firstKey = Object.keys(inputData)[0];
  if (Array.isArray(inputData[firstKey])) {
    rawTextArray = inputData[firstKey];
  }
}

// Global structural validation fallback
if (!Array.isArray(rawTextArray)) {
  return [{ json: { error: "Failed to locate array wrapper", debug_received: typeof inputData } }];
}

// Map each plain text block into separate unique n8n items
return rawTextArray.map(postText => {
  return {
    json: {
      text_block: postText
    }
  };
});

